files.content:
:root {
  --bg: #2d1b69;
  --card-bg: #f5e6d3;
  --primary: #ff8c42;
  --secondary: #4ecdc4;
  --text: #2d1b69;
  --bar-bg: #d4c4b0;
  --hunger-color: #ff6b6b;
  --happiness-color: #ffd93d;
  --energy-color: #6bcb77;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 16px;
  background: var(--bg);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-card {
  background: var(--card-bg);
  border-radius: 24px;
  padding: 32px 24px;
  width: 100%;
  max-width: 400px;
  box-shadow: 0 8px 32px rgba(0,0,0,0.3);
  text-align: center;
}

h1 {
  font-size: 28px;
  color: var(--text);
  margin-bottom: 24px;
  letter-spacing: 1px;
}

.pet-container {
  display: flex;
  justify-content: center;
  margin-bottom: 16px;
}

.pet {
  width: 120px;
  height: 120px;
  background: var(--primary);
  border-radius: 20px;
  position: relative;
  image-rendering: pixelated;
  box-shadow: inset -8px -8px 0 rgba(0,0,0,0.1);
  transition: transform 0.2s;
}

.pet::before {
  content: '';
  position: absolute;
  top: -12px;
  left: 20px;
  width: 24px;
  height: 24px;
  background: var(--primary);
  border-radius: 4px;
  transform: rotate(45deg);
  box-shadow: 56px 0 0 var(--primary);
}

.eye {
  position: absolute;
  width: 16px;
  height: 16px;
  background: var(--text);
  border-radius: 50%;
  top: 40px;
}

.eye.left { left: 30px; }
.eye.right { right: 30px; }

.mouth {
  position: absolute;
  width: 40px;
  height: 20px;
  border-bottom: 4px solid var(--text);
  border-radius: 0 0 40px 40px;
  bottom: 30px;
  left: 50%;
  transform: translateX(-50%);
}

.mood {
  font-size: 18px;
  color: var(--text);
  margin-bottom: 24px;
  min-height: 27px;
  font-weight: 500;
}

.stats {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 32px;
}

.stat {
  display: flex;
  align-items: center;
  gap: 12px;
}

.stat-label {
  font-size: 16px;
  font-weight: 600;
  color: var(--text);
  width: 80px;
  text-align: left;
}

.bar-bg {
  flex: 1;
  height: 20px;
  background: var(--bar-bg);
  border-radius: 10px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  width: 100%;
  transition: width 0.3s ease;
  border-radius: 10px;
}

.bar-fill.hunger { background: var(--hunger-color); }
.bar-fill.happiness { background: var(--happiness-color); }
.bar-fill.energy { background: var(--energy-color); }

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 18px;
  font-weight: 600;
  padding: 12px 24px;
  border: none;
  border-radius: 12px;
  background: var(--secondary);
  color: var(--text);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  min-width: 80px;
}

button:hover {
  background: #3db8af;
}

button:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.95);
}

@media (max-width: 400px) {
  .game-card {
    padding: 24px 16px;
  }
  .stat-label {
    width: 70px;
    font-size: 14px;
  }
  button {
    padding: 10px 18px;
    font-size: 16px;
    min-width: 70px;
  }
}

const state = {
  hunger: 80,
  happiness: 80,
  energy: 80
};

const hungerBar = document.getElementById('hunger-bar');
const happinessBar = document.getElementById('happiness-bar');
const energyBar = document.getElementById('energy-bar');
const moodText = document.getElementById('mood-text');
const pet = document.getElementById('pet');

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

function updateUI() {
  hungerBar.style.width = state.hunger + '%';
  happinessBar.style.width = state.happiness + '%';
  energyBar.style.width = state.energy + '%';

  let mood = 'Your pet is feeling great!';
  let petClass = '';

  if (state.hunger < 30) {
    mood = 'Your pet is very hungry!';
    petClass = 'hungry';
  } else if (state.happiness < 30) {
    mood = 'Your pet is sad and needs play!';
    petClass = 'sad';
  } else if (state.energy < 30) {
    mood = 'Your pet is exhausted!';
    petClass = 'tired';
  } else if (state.hunger < 60 || state.happiness < 60 || state.energy < 60) {
    mood = 'Your pet could use some attention.';
  }

  moodText.textContent = mood;
  pet.className = 'pet ' + petClass;
}

function feed() {
  state.hunger = clamp(state.hunger + 20);
  state.energy = clamp(state.energy - 5);
  updateUI();
}

function play() {
  state.happiness = clamp(state.happiness + 20);
  state.energy = clamp(state.energy - 15);
  state.hunger = clamp(state.hunger - 10);
  updateUI();
}

function sleep() {
  state.energy = clamp(state.energy + 30);
  state.hunger = clamp(state.hunger - 10);
  updateUI();
}

document.getElementById('feed-btn').addEventListener('click', feed);
document.getElementById('play-btn').addEventListener('click', play);
document.getElementById('sleep-btn').addEventListener('click', sleep);

updateUI();
